<script setup lang="ts">
import {ref} from 'vue'
import AppIcon from './AppIcon.vue'
import {work,restoreSession,signOut} from '../workspace'
const password=ref(''),busy=ref(false),error=ref('')
async function resume(){if(busy.value)return;busy.value=true;error.value='';try{await restoreSession(password.value);password.value=''}catch(e:any){error.value=e.message}finally{busy.value=false}}
function exit(){uni.showModal({title:'返回登录页？',content:'当前尚未提交的填写将被放弃。你也可以继续在此核实原账号，保留当前页面。',confirmText:'返回登录',cancelText:'继续填写',success:r=>{if(r.confirm){password.value='';signOut()}}})}
</script>
<template><view class="session-gate" @click.stop @touchmove.stop.prevent><view class="session-gate-content"><AppIcon name="locked" :size="34"/><text class="session-gate-title">核实登录后，继续当前填写</text><text class="session-gate-message">{{work.authMessage||'登录已失效'}}。当前内容尚未提交，仍保留在本次页面中。</text><text class="label">当前账号</text><text class="session-account">{{work.data?.account.display_name}} · {{work.data?.account.login_name}}</text><text class="label">账号密码</text><input class="input" v-model="password" password aria-label="重新核实账号密码" @confirm="resume"/><view v-if="error" class="error">{{error}}</view><button class="primary" :disabled="busy||!password" @click="resume">{{busy?'正在核实…':'核实并返回当前页面'}}</button><button class="text-button" :disabled="busy" @click="exit">返回登录页</button><text class="session-note">仅恢复原账号仍有效的同一岗位范围。资料会在提交时再次核对当前版本。</text></view></view></template>
<style scoped>.session-gate{position:fixed;inset:0;z-index:9999;background:#f2f5f8;display:flex;align-items:center;justify-content:center;padding:26px}.session-gate-content{width:100%;max-width:440px;background:#fff;padding:32px;border:1px solid #e3e8ef;border-radius:12px}.session-gate-title{display:block;font-size:22px;font-weight:600;line-height:1.6;margin:20px 0 12px}.session-gate-message{display:block;font-size:14px;line-height:1.9;color:#758296;margin-bottom:24px}.session-account{display:block;font-size:15px;margin-bottom:22px}.session-gate-content>.primary{width:100%;margin-top:20px}.session-gate-content>.text-button{width:100%;justify-content:center;margin-top:12px}.session-gate-content>.error{margin-top:16px}.session-note{display:block;font-size:12px;line-height:1.8;color:#758296;margin-top:14px}@media(max-width:680px){.session-gate-content{padding:24px 20px}.session-gate-title{font-size:20px}}
</style>
